\textnormal{Let $f$ and $g\notin\{1,f\}$ be two holomorphic eta quotients.
If the eta quotient $f/g$ is holomorphic,
we call $g$ a \emph{proper factor} of $f$.
A holomorphic eta quotient $f$ is \emph{reducible} 
if it has a proper factor. Otherwise, we call $f$ \emph{ir{\-}reducible}}.
\label{10:48AM}

\textnormal{
Given an integer $N>1$, let 
$N=\prod_{p|N}p^{n_p}$ be the prime factorization of $N$. Let $\mathbb{D}_N$ denote the set of all divisors of $N$.
Let $\{\alpha_p\}_{p|N}$
be a sequence with $\alpha_p\in\{0,1\}$ for all $p$
such that $\alpha_p=1$ if $n_p=1$. Let
\begin{equation}
 \Lambda_N:=\Bigg\{\prod_{p|N}p^{\beta_p}\in\mathbb{D}_N\ : \text{ 
 $\exists 
 \ p_0|N$ with} \ \beta_{p_0}\in\{\alpha_{p_0}, n_{p_0}\}\Bigg\}.
\label{12:00PM}\end{equation}
A special set of cusp classes of $\Gamma_0(N)$ contains only the cusp classes represented by the reciprocals of the elements of $\Lambda_N$.
}
\label{9:22AM}

\label{ppi}
A generic irreducible holomorphic eta quotient of a prime power level is uniquely identified by its orders of vanishing
at the cusps $0$ and $\infty$.

For a prime $p$ and an $n\in\mathbb{N}$, the primitive 
cuspidal eta quotient $\mathcal{H}_{p,n}$ is irreducible except only for the cases in \eqref{redH}.
\label{prp1}

\label{12:42PM} For all $k\in\mathbb{N}$, the $k$-th Mersmann level $\mathcal{M}_k$ is divisible by
    $$\prod_{\substack{p \ \text{ prime}\\p\leq\sqrt{k-\frac34}+\frac32}}p^{\varepsilon_{p,k}},$$
where $$\varepsilon_{p,k}=\begin{cases}
2k&\text{if \ $p=2$}\\
\mathbf{I}_{\mathbb{N}}\Big(\frac{2k+p-3}{(2p-3)(p-1)}+1  \Big)&\text{if \ $p>2$ and  $k\notin2\mathbb{N}$}\\
\mathbf{I}_{\mathbb{N}_{>3}}\Big(\frac{k-2}{(p-1)(p-2)}+1  \Big)&\text{if \ $p>2$ and  $k\in2\mathbb{N}$.}\\
\end{cases}$$
 Here $$\mathbf{I}_{\mathbb{N}}(n)=\begin{cases}
n&\text{if $n\in\mathbb{N}$}\\0&\text{otherwise}
 \end{cases}
 \text{ \ and \ \ }
 \mathbf{I}_{\mathbb{N}_{>3}}(n)=\begin{cases}
n&\text{if $n\in\mathbb{N}$ and $n>3$}\\0&\text{otherwise.}
 \end{cases}
 $$

From \eqref{12:24AM}, we have
\begin{equation}
 B_N=\bigotimes_{\substack{p^n\|N\\\text{$p$ prime}}}B_{p^n}.

\end{equation}
By elementary row and column operations\footnote{i.e. by swapping rows (resp. columns) and subtracting a multiple of a row (resp. a column) from another.},
each $B_{p^n}$ can be reduced
to a diagonal matrix\footnote{i.e. the Smith Normal Form of $B_{p^n}$ (see~\cite{a}).} $D_{p^n}$ with integer entries.
In other words,
there exist $U_{p^n}, V_{p^n}\in\operatorname{GL}_{n+1}(\mathbb{Z})$ 
such that $D_{p^n}=U_{p^n} B_{p^n} V_{p^n}$. In \S\ref{mi}, we provide 
the matrices $U_{p^n}$ and $V_{p^n}$ explicitly\footnote{
Up to 
rearrangement of the
diagonal 
entries 
of $D_{p^n}$, which 
is equivalent to
permutation of the 
rows of $U_{p^n}$ and the columns of $V_{p^n}$ accordingly.}
such that
\begin{equation}
D_{p^n}=\operatorname{diag}(1,1,\hdots,1,p^{n-1},p^{n-1}(p^2-1)).
\label{6:48AM}\end{equation}
Define 
\begin{equation}
U_N:=\bigotimes_{\substack{p^n\|N\\\text{$p$ prime}}}U_{p^n}, \ \ V_N:=\bigotimes_{\substack{p^n\|N\\\text{$p$ prime}}}V_{p^n} \text{ \ and \ } D_N:=\bigotimes_{\substack{p^n\|N\\\text{$p$ prime}}}D_{p^n}.
\label{10:20AM}\end{equation}
Then $U_N,V_N\in\operatorname{GL}_{\mathrm{d}(N)}(\mathbb{Z})$ and 
\begin{equation}D_N=U_NB_NV_N.\label{9:49AM}\end{equation}
In particular, since $U_{N}$ is invertible over $\mathbb{Z}$,
left multiplication by $U_{N}^{-1}$ induces an automorphism of $\mathbb{Z}^{\mathbb{D}_{N}}$, i.e.
$U_{N}^{-1}\mathbb{Z}^{\mathbb{D}_{N}}=\mathbb{Z}^{\mathbb{D}_{N}}$.
It follows from \eqref{9:49AM} that 
\begin{equation}
    B^{-1}_N\mathbb{Z}^{\mathbb{D}_N}= B^{-1}_NU_N^{-1}\mathbb{Z}^{\mathbb{D}_N}=V_ND^{-1}_N\mathbb{Z}^{\mathbb{D}_N}.
\label{9:59AM}\end{equation}
Let $X\in B_N\cdot[0,1)^{\mathbb{D}_N}\cap\mathbb{Z}^{\mathbb{D}_N}$ be such that $\eta^X$ is 

holomorphic.
Then 
\begin{equation}
Y:=B_N^{-1}X\in[0,1)^{\mathbb{D}_N}\cap B^{-1}_N\mathbb{Z}^{\mathbb{D}_N}=[0,1)^{\mathbb{D}_N}\cap V_ND^{-1}_N\mathbb{Z}^{\mathbb{D}_N},
\label{2:33AM}\end{equation}
where the last equality follows from \eqref{9:59AM},
Since $[0,1)^{\mathbb{D}_N}\cap V_ND^{-1}_N\mathbb{Z}^{\mathbb{D}_N}$ is a complete set of the coset representatives of $\mathbb{Z}^{\mathbb{D}_N}$ in $V_ND^{-1}_N\mathbb{Z}^{\mathbb{D}_N}$, there is natural a bijection between 
$[0,1)^{\mathbb{D}_N}\cap V_ND^{-1}_N\mathbb{Z}^{\mathbb{D}_N}$

and $(V_ND^{-1}_N\mathbb{Z}^{\mathbb{D}_N})/\mathbb{Z}^{\mathbb{D}_N}$. In particular, since $D_N\in\mathbb{Z}^{\mathbb{D}_N\times\mathbb{D}_N}$ is a diagonal matrix, we have
\begin{equation}
    Y\equiv \sum_{d|N}\frac{\ell_d}{D_N(d,d)}V_N(\hspace{1.3pt}\underline{\hspace{5pt}}\hspace{1.3pt}\hspace{1.3pt},d)\pmod{\mathbb{Z}^{\mathbb{D}_N}},
\label{10:01AM}\end{equation}
where $\ell_d\in\mathbb{Z}$ with $0\leq\ell_d< D_N(d,d)$ and 
$V_N(\hspace{1.3pt}\underline{\hspace{5pt}}\hspace{1.3pt}\hspace{1.3pt},d)$ denotes the column of $V_N$ indexed by $d\in\mathbb{D}_N$. That implies, if $d\in\mathbb{D}_N$
is such that $D_N(d,d)=1$, then $\ell_d=0$. 
Let 
\begin{equation}
\Lambda_N':=\{d\in\mathbb{D}_N \ : \ D_N(d,d)>1\}
\label{7:58PM}\end{equation}
and let $C_{\Lambda_N'}\in\mathbb{Z}^{\mathbb{D}_N\times\Lambda_N'}$ be defined by 
$C_{\Lambda_N'}(t,d)=V_N(t,d)$ for all $t\in\mathbb{D}_N$ and $d\in\Lambda_N'$. Then
\eqref{10:01AM} is equivalent to
\begin{equation}
Y\equiv C_{\Lambda_N'}\widetilde{\ell}\pmod{\mathbb{Z}^{\mathbb{D}_N}},
\label{10:03AM}
\end{equation}
where
$\widetilde{\ell}\in[0,1)^{\Lambda_N'}$ be defined by $\widetilde{\ell}_d:=\ell_d/D_N(d,d)$ for all $d\in\Lambda_N'$. Also, for $\Lambda_N$ as in $\eqref{12:00PM}$, let $\widetilde{Y}\in[0,1)^{\Lambda_N}$ be defined by \begin{equation}
    \widetilde{Y}_t:=Y_t \ \text{ for all $t\in\Lambda_N$.}
\label{2:29AM}\end{equation}  
Let $\lambda_N:=|\Lambda_N|$.
It follows from \eqref{6:48AM}, \eqref{10:20AM} and \eqref{7:58PM} that
the cardinality of $\Lambda_N'$ is given by the quantity on the right hand side \eqref{6:04AM}. Thus, we obtain

$$|\Lambda_N'|=|\Lambda_N|=\lambda_N.$$
Let $E_N\in\mathbb{Z}^{\Lambda_N\times\Lambda_N'}$ be defined by
\begin{equation}
    E_N(t,d)=V_N(t,d) \  \text{ for all $t\in\Lambda_N$ and $d\in\Lambda_N'$.}
\label{1:12AM}\end{equation}
It follows from \eqref{10:03AM} that 
\begin{equation}
    \widetilde{Y}\equiv E_N\widetilde{\ell}\pmod{\mathbb{Z}^{\Lambda_N}}.
\label{1:38AM}\end{equation}
In Lemma~\ref{1:36AM}, we show that $E_N$ is invertible over $\mathbb{Z}$. So, $E_N^{-1}\mathbb{Z}^{\Lambda_N}=\mathbb{Z}^{\Lambda_N}$. Hence, \eqref{1:38AM} is equivalent to 
\begin{equation}
    \widetilde{\ell}\equiv E_N^{-1}\widetilde{Y}\pmod{\mathbb{Z}^{\Lambda_N}}.
\label{2:30AM}\end{equation}
Since $Y=B_N^{-1}X$, from  \eqref{28.08.2015A}, \eqref{11:53AM}, \eqref{28.04} and \eqref{2:29AM},
it follows that the entries of $\widetilde{Y}_t$ are the normalized orders of the          
holomorphic eta quotient $\eta^X$ at the special set of cusp classes of $\Gamma_0(N)$ which are represented by the reciprocals of the elements of $\Lambda_N$ (see \eqref{12:00PM}).
Hence, the claim follows from \eqref{2:30AM}, \eqref{10:03AM} and \eqref{2:33AM}.

Let $E_N$ be as in \eqref{1:12AM}. 
Then $E_N\in\operatorname{GL}_{\lambda_N}(\mathbb{Z}).$
\label{1:36AM}

For a prime $p$ and an $n\in\mathbb{N}$, 

$V_{p^n}\in\operatorname{GL}_{n+1}(\mathbb{Z})$ is given by (see \S\ref{mi}):
\begin{equation}
V_{p^n}=
\begin{cases}\begin{pmatrix}1&p\\0&1\end{pmatrix}&\text{if $n=1$}\\
\\
\begin{pmatrix}1&

    0\hspace{2pt}\cdots\hspace{2pt}0&1&p^n\\
    0& 0\hspace{2pt}\cdots\hspace{2pt}0

    &1&p^{n-2}\\\begin{matrix}0\\\vdots\\0\end{matrix}

&L_{p^n}&\begin{matrix}\ast\\\vdots\\\ast\end{matrix}&\begin{matrix}\ast\\\vdots\\ \ast\end{matrix}\\
 0&0\hspace{2pt}\cdots\hspace{2pt}0

    &0&1
    \end{pmatrix}

    &\text{otherwise,}
    \end{cases}
\label{5:55AM}\end{equation}
where $L_{p^n}\in\operatorname{GL}_{n-2}(\mathbb{Z})$ 



is defined by
\begin{equation}L_{p^n}(i,j)=\begin{cases}
-p^{i-j}&\text{if  $i\geq j$,}\\  
0&\text{otherwise.}    
\end{cases}
\label{10:47AM}\end{equation}
From \eqref{12:00PM}, \eqref{7:58PM} and \eqref{6:48AM}, 
it follows that $\Lambda_p=\Lambda_p'=\{p\}$. Hence, from \eqref{5:55AM} 
we obtain that
$E_p=[V_p(p,p)]=[1]\in\operatorname{GL}_1(\mathbb{Z}).$

For $n>1$, it follows from \eqref{12:00PM} that 
$\Lambda_{p^n}=\{1,p^n\}\text{ \ or \ }\{p,p^n\}$
while \eqref{7:58PM} and \eqref{6:48AM} imply that $\Lambda_{p^n}'=\{p^{n-1},p^n\}.$
So, $\eqref{5:55AM}$ implies that
\begin{equation}
    E_{p^n}=\begin{pmatrix}1&p^n\\0&1\end{pmatrix} \text{ \ or \ }\begin{pmatrix}1&p^{n-2}\\0&1\end{pmatrix},
\end{equation}
both of which belong to $\operatorname{GL}_2(\mathbb{Z})$ for all $n>1$.
Thus, the claim holds for all prime powers. 

Now, it suffices to show that if the claim holds for an $M\in\mathbb{N}$, then it also holds for $p^nM$ for all $n\in\mathbb{N}$, where $p$ is a prime such that $p\nmid M$. 

From $\eqref{10:20AM}$, we have $V_{p^nM}=V_{p^n}\otimes V_M$ and $D_{p^nM}=D_{p^n}\otimes D_M$. So, \eqref{6:48AM} implies that the diagonal\footnote{hence, a block diagonal matrix} matrix $D_{p^nM}\in\mathbb{Z}^{\mathbb{D}_{p^nM}\times\mathbb{D}_{p^nM}}$ is given by
\begin{equation}D_{p^nM}=\mathrm{diag}(D_M,D_M,\ldots,D_M,p^{n-1}D_M, p^{n-1}(p^2-1)D_M)
\label{8:21AM}\end{equation}
and from \eqref{5:55AM}, it follows that $V_{p^nM}\in\operatorname{GL}_{\mathrm{d}(p^nM)}(\mathbb{Z})$ is of the form
\begin{equation}
V_{p^nM}=
\begin{cases}\begin{pmatrix}V_M&{\huge\ast}\\0&V_M\end{pmatrix}
&\text{if $n=1$}\\
\\
\begin{pmatrix}V_M&
    0&V_M&{\huge\ast}\\
    0& 0
    &V_M&{\huge\ast}\\
0&L_{p^n}\otimes V_M&{\huge\ast}&{\huge\ast}\\
 0&0
    &0&V_M
    \end{pmatrix}
    &\text{otherwise.}
    \end{cases}
\label{1:37PM}\end{equation}
It follows from \eqref{12:00PM}, \eqref{7:58PM} and \eqref{8:21AM} and \eqref{1:37PM} that  
$E_{p^nM}\in\mathbb{Z}^{\Lambda_{\Lambda_{p^nM}}\times\Lambda'_{\lambda_{p^nM}}}$ is of the form
\begin{equation}
E_{p^nM}=\begin{cases}
\begin{pmatrix}E_M&{\huge \ast}\\0&V_M\end{pmatrix}
&\text{if $n=1$}\\ \\
\begin{pmatrix}
    E_M&0&R_{\Lambda_M}&{\huge \ast}\\
    0&0&V_M&{\huge \ast}\\
    0&L_{p^n}\otimes E_M&{\huge \ast}&{\huge \ast}\\
    0&0&0&V_M
\end{pmatrix}

&\text{if $n>1$ and $\alpha_p=1$}\\ \\
\begin{pmatrix}
        C_{\Lambda_M'}&0&V_M&{\huge \ast}\\
    0&0&R_{\Lambda_M}&{\huge \ast}\\
    0&L_{p^n}\otimes E_M&{\huge \ast}&{\huge \ast}\\
    0&0&0&V_M
\end{pmatrix}
&\text{if $n>1$ and  $\alpha_p=0$}
\end{cases}
\label{10:35AM}\end{equation}
where 
$C_{\Lambda_M'}$ is the submatrix of $V_M\in\mathbb{Z}^{\mathbb{D}_M\times\mathbb{D}_M}$, 
composed of those columns of $V_M$ which are indexed by  $\Lambda_M'$ and $R_{\Lambda_M}$ is the submatrix of $V_M$, 
composed of those rows of $V_M$ which are indexed by  $\Lambda_M$. 


We note that $E_{pM}$ is already in a block upper triangular form, whereas
for $n>1$, after a set of column operations interchanging the second and third column
blocks 

of $E_{p^nM}$ in \eqref{10:35AM}, we also obtain a block upper triangular matrix with four diagonal blocks if $\alpha_p=1$, viz. $E_M, V_M,L_{p^n}\otimes E_M$ and $V_M$ 
 and three diagonal blocks if $\alpha_p=0$, viz. 
 \begin{equation}
 \begin{pmatrix}
        C_{\Lambda_M'}&V_M\\0&R_{\Lambda_M}\end{pmatrix}, \ L_{p^n}\otimes E_M \text{ \ and \ } V_M.
        \label{7:19AM}\end{equation}
Since by induction hypothesis, $E_M\in\operatorname{GL}_{\lambda_M}(\mathbb{Z})$ and since
$L_{p^n}\in\operatorname{GL}_{n-2}(\mathbb{Z})$ (see~\eqref{10:47AM}), it follows that 
$$L_{p^n}\otimes E_M\in\operatorname{GL}_{(n-2)\lambda_M}(\mathbb{Z}).$$

Since the determinant of a block upper triangular matrix is 
the product of the determinants of its diagonal blocks\footnote{See Lemma~1.25 in \cite{xz}.} 
and since $E_M,V_M$ and $L_{p^n}\otimes E_M$ are invertible over $\mathbb{Z}$,
the claim follows in both the cases where $n=1$ and $n>1$ with $\alpha_p=1$.

In the remaining case, where $n>1$ and $\alpha_p=0$, the diagonal blocks
after a set of column operations on $E_{p^nM}$, are given in
\eqref{7:19AM}. So, invertibility of $L_{p^n}\otimes\mathbb{Z}$ and $V_M$ over $\mathbb{Z}$ implies that
$\det E_{p^nM}=\pm\det Z_M$, where 


\begin{equation} Z_{M}:=\begin{pmatrix}
        C_{\Lambda_M'}&V_M\\0&R_{\Lambda_M}\end{pmatrix}.




\label{4:21PM}\end{equation}

Since the Schur complement\footnote{See \S1.11 in \cite{xz}.}

of $V_M$ is $-E_M$ in the matrix obtained
after interchanging  either the row blocks or the column blocks of $Z_M$ in \eqref{4:21PM},





it follows that $$\det Z_M=\pm(\det E_M).(\det V_M)=\pm1.$$ Thus, we obtain 
that 
$E_{p^nM}\in\operatorname{GL}_{\lambda_{p^nM}}(\mathbb{Z}).$ Hence, the claim follows.

From \eqref{5:25AM} and \eqref{equ1}, it follows that 
\begin{equation}
  \mathcal{F}_{p^n}=\begin{cases}\displaystyle{(\eta\eta_p)^{p-1}}&\text{ if $n=1$}\\ \\
  \displaystyle{\eta_p^{p^2-1}}&\text{ if $n=2$}\\ 

  \displaystyle{(\eta_p\eta_{p^{n-1}})^{p^2-p}\prod_{j=2}^{n-2}\eta_{p^j}^{(p-1)^2}}&\text{ if $n\geq3$.}
                    \end{cases}
\end{equation}
Hence, from \eqref{hpn} we obtain
\begin{equation}
  \frac{\mathcal{F}_{p^n}}{\mathcal{H}_{p,n}}=\begin{cases}\displaystyle{(\eta\eta_p)^{p-2}}&\text{ if $n=1$}\\ \\

    \displaystyle{(\eta\eta_{p^n})^{p-1}\eta_p^{p-2}\prod_{s=1}^{n/2-1}\frac{\eta_{p^{2s-1}}\eta_{p^{2s+1}}^{p-1}}{\eta_{p^{2s}}}}&\text{ if $n\geq2$ is even.}\\

 \displaystyle{(\eta\eta_{p^n})^{p-1}(\eta_p\eta_{p^{n-1}})^{p-2}\prod_{j=2}^{n-2}\eta_{p^j}^{p-1}}&\text{ if $n\geq3$ is odd.}
                    \end{cases}

\label{12:26PM}\end{equation}
Since for all $s\in\mathbb{N}$, the eta quotient ${\eta_{p^{2s-1}}\eta_{p^{2s+1}}^{p-1}}/{\eta_{p^{2s}}}$ is a rescaling of ${\eta\eta_{p^2}^{p-1}}/{\eta_p}$, which is 
a holomorphic eta quotient\footnote{Since $A_{p^2}$ is diagonally dominant (see~\eqref{23July}) and since $p-1\geq1$, the orders of vanishing of ${\eta\eta_{p^2}^{p-1}}/{\eta_p}$
at both the cusps $1$ and $1/p^2$ of $\Gamma_0(p^2)$ (corresponding to the first and last rows of $A_p^2$) are nonnegative. Hence, we only require to 
check the nonnegativity of the order of vanishing of ${\eta\eta_{p^2}^{p-1}}/{\eta_p}$ at the cusp $1/p$, which is $(1-p+(p-1))/24=0$ (see~\eqref{27.04.2015.1}).}
of level $p^2$, and since the cuspidal eta quotient $\eta$ is a factor of ${\mathcal{F}_{p^n}}/{\mathcal{H}_{p,n}}$ except for the case $p^n=2$, it follows that unless\footnote{${\mathcal{F}_{2}} = {\mathcal{H}_{2,1}}$.} $p^n=2$, the eta quotient ${\mathcal{F}_{p^n}}/{\mathcal{H}_{p,n}}$ is cuspidal.

Let $,Y,Y',Y''\in\mathbb{Q}^{\mathbb{D}_{p^n}}$ be such that\footnote{The invertibility of $B_{p^n}$ follows from \eqref{28.08.2015A}} 
\begin{equation}
 Y=B^{-1}_{p^n}X, \ Y'=B^{-1}_{p^n}X' \text{ \ and  \ }Y''=B^{-1}_{p^n}X''.
\label{11:58AM}
\end{equation}
Since each row of $B^{-1}_{p^n}$ is a positive multiple of a row of $A_{p^n}$ (see~\eqref{10:39AM} and \eqref{mtn}) and since $\mathcal{H}_{p,n}=h\times h'$
where both $h$ and $h'$ are holomorphic, it follows from \eqref{9:44AM} and \eqref{11:58AM} that
\begin{equation}
Y=Y'+Y'',
\nonumber\end{equation}
where  all the entries of $Y,Y'$ and $Y''$ are nonnegative (see~\eqref{28.04}). Hence, it suffices to show that  $Y\in[0,1)^{\mathbb{D}_{p^n}}.$
Since for $p^n>2$, both $\mathcal{H}_{p,n}$ and ${\mathcal{F}_{p^n}}/{\mathcal{H}_{p,n}}$ are cuspidal,

it follows from Corollary~\ref{5:46AM} and \eqref{11:58AM} that $Y\in(0,1)^{\mathbb{D}_{p^n}}$.

For $n\leq 3$, the claim holds trivially. For $n>3$, the proofs of the 
equalities of the corresponding matrix entries             
in each of these matrix relations

involve at most summation of some geometric series. For example,
consider the identity $D_{p^n}=U_{p^n}B_{p^n}V_{p^n}$.






























 It is equivalent to $D_{p^n}V'_{p^n}=U_{p^n}B_{p^n}$, assuming  $V_{p^n}V'_{p^n}=I_{p^n}$. Now  from \eqref{6:48AM} and \eqref{v'},  we see that for $i,j\in\{0,\hdots,n\}$, the $(i,j)$-th entry of $D_{p^n}V'_{p^n}$ is given by
\begin{equation*}\begin{tabular}{ l|c|c|c| }
\multicolumn{1}{r}{}
 & \multicolumn{1}{c}{$j=0$}
 &  \multicolumn{1}{c}{$0<j<n$}
 & \multicolumn{1}{c}{$j=n$}\\

\cline{2-4}

$i=0$&1 &$\begin{matrix}-1\quad&0\quad&\hdots\quad&0\quad\end{matrix}$&$-p^{n-2}(p^2-1)$\\
\cline{2-4}

$0<i<n-1$ & 0& $\left\{\begin{array}{cl}
p&\text{if  $i=j$,}\\
-1\hspace{8pt}&\text{if  $i=j-1$,}\\
0&\text{otherwise.}    
      \end{array}\right.$&$-p^{n-i-2}(p^2-1)$\\

\cline{2-4}

$i=n-1$ & 0 & $\begin{matrix}p^{n-1}\quad&0\quad&\hdots\quad&0\quad\end{matrix}$&$-p^{2n-3}$\\

\cline{2-4}
$i=n$ &0 & $0$&$p^{n-1}(p^2-1$)\\
\cline{2-4}
\end{tabular}\hspace{8pt}.\end{equation*}

If we consider the case $0<i<n-1$ and $0<j<n$, then from
$(\ref{u})$ and $(\ref{equ1})$ it follows that the product of $U_{p^n}(p^i,\hspace{1.3pt}\hspace{1.3pt}\underline{\hspace{5pt}}\hspace{1.3pt})$, i.e. the $i$-th row of $U_{p^n}$
and $B_{p^n}(\hspace{1.3pt}\underline{\hspace{5pt}}\hspace{1.3pt}\hspace{1.3pt},p^j)$, i.e. the $j$-th column of $B_{p^n}$ is \begin{align*}-\sum_{k=i+1}^np^{k-i-1}\hspace{2pt}B_{p^n}(p^k,p^j)&=\sum_{k=i+1}^np^{k-i-1}(p\hspace{1pt}\delta_{|k-j|\hspace{1pt},\hspace{1pt}1}-(p^2+1)\hspace{1pt}\delta_{k,\hspace{1pt}j})\\
&=\sum_{k=\max\{i+1,\hspace{1pt}j-1\}}^{j+1}p^{k-i-1}(p\hspace{1pt}\delta_{|k-j|\hspace{1pt},\hspace{1pt}1}-(p^2+1)\hspace{1pt}\delta_{k,\hspace{1pt}j})\\
&=\begin{cases}

\hspace{8pt}0&\text{ if $j<i$,}\\
\hspace{8pt}p&\text{ if $j=i$,}\\
-1&\text{ if $j=i+1$,}\\
\hspace{8pt}0&\text{ if $j>i+1$,}
\end{cases}

\end{align*}
where $\delta$ is the Kronecker delta function. So, the claim holds in this case.

Again, for $i=n-1$ and $0<j<n$, we have

\begin{align*}
U_{p^n}(p^{n-1},\hspace{1.3pt}\hspace{1.3pt}\underline{\hspace{5pt}}\hspace{1.3pt})\cdot &B_{p^n}(\hspace{1.3pt}\underline{\hspace{5pt}}\hspace{1.3pt}\hspace{1.3pt},p^j)\\
&=
-\sum_{k=1}^np^{n-k}\cdot\frac{p^{2(k-1)}-1}{p^2-1}\cdot\hspace{2pt}B_{p^n}(p^k,p^j)\\

&=\sum_{k=\max\{2,\hspace{1pt}j-1\}}^{j+1}p^{n-k}\cdot\frac{p^{2(k-1)}-1}{p^2-1}\cdot\left(p\hspace{1pt}\delta_{|k-j|\hspace{1pt},\hspace{1pt}1}-(p^2+1)\hspace{1pt}\delta_{k,\hspace{1pt}j}\right)\\
&=\begin{cases}

p^{n-1}&\text{ if $j=1$,}\\
0&\text{ otherwise,}
\end{cases}
\end{align*}

Thus, the claim also holds in this case.


The rest of the proof is analogous and requires only routine verifications as above.

For each prime $p$, 
there does not exist any primitive and irreducible holomorphic eta quotient of level $p^3$.
\label{00:13AM}

Given two irreducible holomorphic eta quotients $f=\prod_{d|M}\eta_d^{X_d}$ and $g=\prod_{\delta|N}\eta_{\delta}^{Y_{\delta}}$ respectively on $\Gamma_0(M)$ and $\Gamma_0(N)$ with mutually coprime $M$ and~$N$, the holomorphic eta quotient $f\circledast g$,
